package com.hbm.network.cargo.request;
import com.hbm.network.cargo.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.*;
import net.minecraft.world.phys.*;
/** Original sequential route/pickup/unload/return-to-dock program, including5-tick handling pauses. */
public final class RequestDrone extends CargoDroneBase {
 public ItemStack heldItem=ItemStack.EMPTY;public final List<Object> program=new ArrayList<>();private int nextActionTimer;public enum DroneProgram{UNLOAD,DOCK}
 public RequestDrone(EntityType<? extends RequestDrone> type,Level level){super(type,level);}@Override public boolean isRequestDrone(){return true;}@Override public double getSpeed(){return .625D;}@Override public void setTarget(double x,double y,double z){super.setTarget(x,y+1,z);}
 @Override public boolean skipAttackInteraction(Entity attacker){if(isRemoved())return false;if(attacker instanceof Player&&!level().isClientSide){discard();if(!heldItem.isEmpty())spawnAtLocation(heldItem,1);spawnAtLocation(CargoDroneContent.droneStack(com.hbm.network.cargo.DroneItem.Kind.REQUEST),1);}return false;}
 private net.minecraft.world.level.block.entity.BlockEntity below(){var start=position();var hit=level().clip(new ClipContext(start,start.add(0,-4,0),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,this));return hit.getType()==HitResult.Type.BLOCK?level().getBlockEntity(hit.getBlockPos()):null;}
 private void sound(){level().playSound(null,getX(),getY(),getZ(),SoundEvent.createVariableRangeEvent(ResourceLocation.parse("hbm:item.unpack")),SoundSource.NEUTRAL,.5F,.75F);}
 @Override public void tick(){super.tick();if(level().isClientSide||sourceSpeed(getDeltaMovement())>=.01)return;if(nextActionTimer>0){nextActionTimer--;return;}if(program.isEmpty()){discard();spawnAtLocation(CargoDroneContent.droneStack(com.hbm.network.cargo.DroneItem.Kind.REQUEST),1);return;}Object next=program.removeFirst();if(next instanceof BlockPos p){setTarget(p.getX()+.5,p.getY(),p.getZ()+.5);}else if(next instanceof CargoRequestStack requested&&heldItem.isEmpty()){if(below() instanceof DroneProviderEntity provider)for(int i=0;i<provider.slots.size();i++){var stack=provider.slots.get(i);if(!stack.isEmpty()&&requested.matches(stack)){heldItem=stack.copy();setAppearance(1);sound();provider.slots.set(i,ItemStack.EMPTY);provider.setChanged();break;}}nextActionTimer=5;}else if(next==DroneProgram.UNLOAD&&!heldItem.isEmpty()){if(below() instanceof DroneRequesterEntity requester){for(int i=9;i<18;i++){var stack=requester.slots.get(i);if(!stack.isEmpty()&&stack.getItem()==heldItem.getItem()&&CargoRequestStack.meta(stack)==CargoRequestStack.meta(heldItem)){int amount=Math.min(stack.getMaxStackSize()-stack.getCount(),heldItem.getCount());stack.grow(amount);heldItem.shrink(amount);}}if(heldItem.getCount()<=0)heldItem=ItemStack.EMPTY;if(!heldItem.isEmpty())for(int i=9;i<18;i++)if(requester.slots.get(i).isEmpty()){requester.slots.set(i,heldItem.copy());heldItem=ItemStack.EMPTY;break;}if(heldItem.isEmpty()){setAppearance(0);sound();}requester.setChanged();}nextActionTimer=5;}else if(next==DroneProgram.DOCK){boolean stored=false;if(below() instanceof DroneDockEntity dock){var item=CargoDroneContent.droneStack(com.hbm.network.cargo.DroneItem.Kind.REQUEST);for(int i=0;i<dock.slots.size();i++){var stack=dock.slots.get(i);if(stack.isEmpty()||DroneDockEntity.isDrone(stack)&&stack.getCount()<64){discard();if(!heldItem.isEmpty()){if(i+1<dock.slots.size()&&dock.slots.get(i+1).isEmpty())dock.slots.set(i+1,heldItem.copy());else spawnAtLocation(heldItem,1);heldItem=ItemStack.EMPTY;}if(stack.isEmpty())dock.slots.set(i,item.copy());else stack.grow(1);level().playSound(null,dock.getBlockPos().getX()+.5,dock.getBlockPos().getY()+.5,dock.getBlockPos().getZ()+.5,com.hbm.registry.HbmSounds.get("block.storageClose"),SoundSource.BLOCKS,2,1);dock.setChanged();stored=true;break;}}}if(!stored){discard();if(!heldItem.isEmpty())spawnAtLocation(heldItem,1);spawnAtLocation(CargoDroneContent.droneStack(com.hbm.network.cargo.DroneItem.Kind.REQUEST),1);}}}
 @Override protected void addAdditionalSaveData(CompoundTag tag){super.addAdditionalSaveData(tag);if(!heldItem.isEmpty())tag.put("held",heldItem.save(registryAccess()));tag.putInt("programSize",program.size());for(int i=0;i<program.size();i++){var data=new CompoundTag();var action=program.get(i);if(action instanceof BlockPos p){data.putString("type","pos");data.putIntArray("pos",new int[]{p.getX(),p.getY(),p.getZ()});}else if(action instanceof CargoRequestStack stack)stack.save(data);else if(action==DroneProgram.UNLOAD)data.putString("type","unload");else if(action==DroneProgram.DOCK)data.putString("type","dock");tag.put("program"+i,data);}}
 @Override protected void readAdditionalSaveData(CompoundTag tag){super.readAdditionalSaveData(tag);heldItem=tag.contains("held")?ItemStack.parseOptional(registryAccess(),tag.getCompound("held")):ItemStack.EMPTY;nextActionTimer=5;program.clear();for(int i=0;i<tag.getInt("programSize");i++){var data=tag.getCompound("program"+i);switch(data.getString("type")){case "pos"->{var p=data.getIntArray("pos");if(p.length>=3)program.add(new BlockPos(p[0],p[1],p[2]));}case "unload"->program.add(DroneProgram.UNLOAD);case "dock"->program.add(DroneProgram.DOCK);case "comp","tag"->program.add(CargoRequestStack.load(data));}}}
}
